package org.zhbot.colossal_wyrm_agility.overlays;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import org.zhbot.colossal_wyrm_agility.ColossalWyrmAgilityConfig;
import org.zhbot.colossal_wyrm_agility.ColossalWyrmAgilityPlugin;
import org.zhbot.colossal_wyrm_agility.enums.Obstacle;

import javax.inject.Inject;
import java.awt.*;

public class ColossalWyrmAgilityPanel extends OverlayPanel {
    private static final long MILLIS_PER_TICK = 600;

    private final Client client;
    private final Notifier notifier;
    private final ColossalWyrmAgilityPlugin plugin;
    private final ColossalWyrmAgilityConfig config;
    private final ProgressBarComponent progressBar = new ProgressBarComponent();

    private boolean justLoggedIn = false;
    private Obstacle obstacle = null;
    private int startTick = -1;
    private long startMS = -1;

    @Inject
    private ColossalWyrmAgilityPanel(Client client, Notifier notifier, ColossalWyrmAgilityPlugin plugin, ColossalWyrmAgilityConfig config)
    {
        this.client = client;
        this.notifier = notifier;
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.TOP_LEFT);
        progressBar.setMinimum(0);
        progressBar.setLabelDisplayMode(ProgressBarComponent.LabelDisplayMode.TEXT_ONLY);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (obstacle == null)
            return null;

        panelComponent.getChildren().clear();

        if (config.overlayPanelTitle())
            panelComponent.getChildren().add(TitleComponent.builder()
                .text(obstacle.getName())
                .color(Color.GREEN)
                .build());

        switch (config.overlayPanelMode())
        {
            case TICKS:
                var ticks = client.getTickCount() - startTick - 1;
                var ticksLeft = obstacle.getTicks() - ticks;

                progressBar.setMaximum(obstacle.getTicks());
                progressBar.setValue(Math.min(ticks, obstacle.getTicks()));
                progressBar.setCenterLabel(ticksLeft + (ticksLeft == 1 ? " tick" : " ticks"));

                break;
            case SECONDS:
                var totalMillis = obstacle.getTicks() * MILLIS_PER_TICK;
                var millis = System.currentTimeMillis() - startMS;
                var millisLeft = totalMillis - millis;

                progressBar.setMaximum(totalMillis);
                progressBar.setValue(Math.min(millis, totalMillis));
                progressBar.setCenterLabel(millisLeft > 0 ? String.format("%.1f seconds", millisLeft / 1000.0) : "Finishing...");
                break;
        }

        panelComponent.getChildren().add(progressBar);

        return super.render(graphics);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN)
            return;

        justLoggedIn = true;
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        if (plugin.outsideWyrmRemainsArea())
            return;

        if (event.getVarbitId() != VarbitID.BUSY)
            return;

        if (justLoggedIn)
        {
            justLoggedIn = false;
            return;
        }

        var player = client.getLocalPlayer();
        if (player == null)
            return;

        var location = player.getWorldLocation();
        if (location == null)
            return;

        if (event.getValue() == 0)
        {
            setObstacle(null);

            var obstacle = Obstacle.getByEndPoint(location);
            if (obstacle == null)
                return;

            if (config.enabledObstacles().contains(obstacle))
                notifier.notify(config.obstacleCompleteNotifications(), "Obstacle \"" + obstacle.getName() + "\" complete");
        }
        else
        {
            var obstacle = Obstacle.getByStartPoint(location);
            if (obstacle == null)
                return;

            if (obstacle.getTicks() > 1)
                setObstacle(obstacle);
        }
    }

    private void setObstacle(Obstacle obstacle)
    {
        this.obstacle = obstacle;
        if (obstacle != null)
        {
            this.startTick = client.getTickCount();
            this.startMS = System.currentTimeMillis();
        }
        else
        {
            this.startTick = -1;
            this.startMS = -1;
        }
    }
}

package org.zhbot.colossal_wyrm_agility.overlays;

import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.ObjectComposition;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.ColorUtil;
import org.zhbot.colossal_wyrm_agility.ColossalWyrmAgilityConfig;
import org.zhbot.colossal_wyrm_agility.ColossalWyrmAgilityPlugin;

import javax.inject.Inject;
import java.awt.*;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class ColossalWyrmAgilityOverlay extends Overlay {
    private final static Set<Integer> TERMITE_IDS = Set.of(
            ObjectID.VARLAMORE_WYRM_AGILITY_BALANCE_1_TERMITES,
            ObjectID.VARLAMORE_WYRM_AGILITY_MULTIJUMP_TERMITES,
            ObjectID.VARLAMORE_WYRM_AGILITY_BASIC_BALANCE_1_TERMITES,
            ObjectID.VARLAMORE_WYRM_AGILITY_BASIC_MONKEYBARS_1_TERMITES,
            ObjectID.VARLAMORE_WYRM_AGILITY_ADVANCED_JUMP_1_TERMITES,
            ObjectID.VARLAMORE_WYRM_AGILITY_ADVANCED_BALANCE_1_TERMITES,
            ObjectID.VARLAMORE_WYRM_AGILITY_ADVANCED_MONKEYBARS_1_TERMITES
    );

    private final Client client;
    private final ClientThread clientThread;
    private final ColossalWyrmAgilityPlugin plugin;
    private final ColossalWyrmAgilityConfig config;

    private final Set<GameObject> termites = new HashSet<>();
    private final Map<Integer, ObjectComposition> termitesMap = new HashMap<>();

    @Inject
    private ColossalWyrmAgilityOverlay(Client client, ClientThread clientThread, ColossalWyrmAgilityPlugin plugin, ColossalWyrmAgilityConfig config)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    public void startup()
    {
        clientThread.invoke(this::loadObjects);
    }

    public void cleanup()
    {
        termites.clear();
        termitesMap.clear();
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (plugin.outsideWyrmRemainsArea())
            return null;

        for (var termites : termites)
        {
            var def = termitesMap.get(termites.getId());
            if (def == null)
                continue;

            var imposter = def.getImpostor();
            if (imposter == null)
                continue;

            if (imposter.getId() != ObjectID.VARLAMORE_WYRM_AGILITY_TERMITES_ACTIVE)
                continue;

            renderObject(graphics, termites, config.termitesColour());
        }

        return null;
    }

    private void renderObject(Graphics2D graphics, GameObject gameObject, Color color)
    {
        var area = gameObject.getConvexHull();
        var mousePosition = client.getMouseCanvasPosition();

        var borderColour = ColorUtil.colorWithAlpha(color, 255);
        OverlayUtil.renderHoverableArea(graphics, area, mousePosition, color, borderColour, borderColour.darker());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        switch (event.getGameState())
        {
            case LOGGED_IN:
                startup();
                break;
            case LOADING:
                cleanup();
                break;
        }
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event)
    {
        var object = event.getGameObject();
        if (!TERMITE_IDS.contains(object.getId()))
            return;

        termites.add(object);
        termitesMap.computeIfAbsent(object.getId(), client::getObjectDefinition);
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned event)
    {
        var object = event.getGameObject();
        if (!TERMITE_IDS.contains(object.getId()))
            return;

        termites.remove(object);
    }

    private void loadObjects()
    {
        if (client.getGameState() != GameState.LOGGED_IN || plugin.outsideWyrmRemainsArea())
            return;

        var worldView = client.getTopLevelWorldView();
        if (worldView == null)
            return;

        var scene = worldView.getScene();
        if (scene == null)
            return;

        var tiles = scene.getTiles()[worldView.getPlane()];
        for (var xTiles : tiles) {
            if (xTiles == null)
                continue;

            for (var tile : xTiles) {
                if (tile == null)
                    continue;

                var gameObjects = tile.getGameObjects();
                if (gameObjects == null)
                    continue;

                for (var object : gameObjects) {
                    if (object == null)
                        continue;

                    if (!TERMITE_IDS.contains(object.getId()))
                        continue;

                    termites.add(object);
                    termitesMap.computeIfAbsent(object.getId(), client::getObjectDefinition);
                }
            }
        }
    }
}

package org.zhbot.colossal_wyrm_agility;

import com.google.gson.Gson;
import com.google.inject.Provides;
import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.events.*;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import org.zhbot.colossal_wyrm_agility.enums.Obstacle;
import org.zhbot.colossal_wyrm_agility.handlers.ColossalWyrmAgilityChatHandler;
import org.zhbot.colossal_wyrm_agility.overlays.ColossalWyrmAgilityOverlay;
import org.zhbot.colossal_wyrm_agility.overlays.ColossalWyrmAgilityPanel;

import java.util.EnumSet;

@Slf4j
@PluginDescriptor(
	name = "Colossal Wyrm Agility",
	description = "A plugin to help AFKing Colossal Wyrm Agility.",
	tags = {"colossal", "wyrm", "agility", "afk"}
)
public class ColossalWyrmAgilityPlugin extends Plugin
{
	private static final WorldArea COLOSSAL_WYRM_REMAINS_AREA = new WorldArea(1623, 2905, 35, 31, 0);

	@Inject
	private Client client;

	@Inject
	private EventBus eventBus;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private ColossalWyrmAgilityConfig config;

	@Inject
	private ColossalWyrmAgilityChatHandler chatHandler;

	@Inject
	private ColossalWyrmAgilityPanel panel;

	@Inject
	private ColossalWyrmAgilityOverlay overlay;

	private boolean inColossalWyrmRemainsArea = false;

	@Override
	protected void startUp() throws Exception
	{
		migrateConfig();
		updateConfig();

		eventBus.register(chatHandler);

		eventBus.register(panel);

		eventBus.register(overlay);
		overlay.startup();
	}

	@Override
	protected void shutDown() throws Exception
	{
		eventBus.unregister(chatHandler);

		eventBus.unregister(panel);
		overlayManager.remove(panel);

		eventBus.unregister(overlay);
		overlayManager.remove(overlay);
		overlay.cleanup();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		var player = client.getLocalPlayer();
		if (player == null)
		{
			inColossalWyrmRemainsArea = false;
			return;
		}

		inColossalWyrmRemainsArea = COLOSSAL_WYRM_REMAINS_AREA.contains2D(player.getWorldLocation());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(ColossalWyrmAgilityConfig.group))
			updateConfig();
	}

	private void updateConfig()
	{
		if (config.overlayPanelEnabled())
			overlayManager.add(panel);
		else
			overlayManager.remove(panel);

		if (config.renderTermites())
			overlayManager.add(overlay);
		else
			overlayManager.remove(overlay);
	}

	@Provides
	ColossalWyrmAgilityConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ColossalWyrmAgilityConfig.class);
	}

	private void migrateConfig()
	{
		var obstacleMinimumTicks = configManager.getConfiguration(ColossalWyrmAgilityConfig.group, "obstacleMinimumTicks");
		if (obstacleMinimumTicks != null)
		{
			log.debug("Migrating \"obstacleMinimumTicks\". Old value: {}", obstacleMinimumTicks);

			var minimumTicks = Integer.parseInt(obstacleMinimumTicks);
			var obstacles = EnumSet.allOf(Obstacle.class);
			obstacles.removeIf(x -> x.getTicks() < minimumTicks);

			var enabledObstacles = gson.toJson(obstacles);
			configManager.setConfiguration(ColossalWyrmAgilityConfig.group, "enabledObstacles", enabledObstacles);
			log.debug("Migrated to \"enabledObstacles\". New value: {}", enabledObstacles);

			configManager.unsetConfiguration(ColossalWyrmAgilityConfig.group, "obstacleMinimumTicks");
			configManager.sendConfig();
		}
	}

	public boolean outsideWyrmRemainsArea()
	{
		return !inColossalWyrmRemainsArea;
	}
}
